import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
k = int(data[1])

if k > n * n:
    print(-1)
else:
    matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        if k <= 0:
            break

        # Place 1 at (i, i)
        if k > 0:
            matrix[i][i] = 1
            k -= 1

        # Try to place two 1s at (i, j) and (j, i)
        for j in range(i + 1, n):
            if k >= 2:
                matrix[i][j] = 1
                matrix[j][i] = 1
                k -= 2
            else:
                break

    if k > 0:
        print(-1)
    else:
        for row in matrix:
            print(" ".join(map(str, row)))

